#include <cstdio>
using namespace std;

typedef long long ll;

int n, k;
ll sum;

int main() {
    scanf("%d%d", &n, &k);
    if (k == 0) {
        printf("%lld\n", (ll)n * n);
        return 0;
    }
    sum = 0;
    for (int i = k + 1; i <= n; i++) {
        ll ni = n / i; // Precompute n / i
        sum += ni * (i - k);
        if (n % i >= k)
 sum += n % i - k + 1;
    }
    printf("%lld\n", sum);
}

